with enriched as (select id, store_name, city, region, opened_date, lead(sqft) over (partition by city, region order by sqft, id) as next_sqft, row_number() over (partition by city, region order by sqft, id) as seq_no from stores) select seq_no, date_trunc('year', opened_date) as year_start, case when seq_no >= 8 then 'PREMIUM' else 'STANDARD' end as seq_no_tier, size(collect_set(city)) as num_cities, count(distinct region) as distinct_regions, sum(case when city = 'New York' then seq_no else 0 end) as new_york_seq_no, count(distinct region) as distinct_regions_2, count(case when city = 'Bangkok' then 1 end) as bangkok_count, count(distinct id) as distinct_ids, grouping_id() as grouping_id from enriched group by grouping sets ((seq_no, date_trunc('year', opened_date), case when seq_no >= 8 then 'PREMIUM' else 'STANDARD' end), (seq_no, date_trunc('year', opened_date)), (seq_no), ()) order by seq_no desc;
